"""Parse arithmetic expressions with nested parentheses into a tree."""

from __future__ import annotations


def parse(expression: str) -> list:
    tokens = expression.replace("(", " ( ").replace(")", " ) ").split()
    tree, rest = _group(tokens)
    if rest:
        raise ValueError("unbalanced expression")
    return tree


def _group(tokens: list[str]) -> tuple[list, list[str]]:
    group: list = []
    while tokens:
        token, tokens = tokens[0], tokens[1:]
        if token == "(":
            child, tokens = _group(tokens)
            group.append(child)
        elif token == ")":
            return group, tokens
        else:
            group.append(token)
    return group, tokens

